function calcPrice(key, sqft, branch) {
  const d = PRICE_DATA[key]; if (!d) return 0;
  const t = (CHICAGO.includes(branch) && d.chicago) ? d.chicago : d.standard;
  const n = Math.max(0, parseInt(sqft)||0);
  const r = t.find(([a,b]) => n>=a && n<=b);
  return r ? r[2] : t[t.length-1][2];
}

